-- Utsav India — full sample dataset for a fresh Supabase project.
-- Run after schema.sql. Safe to re-run: rows are matched by stable UUID.
-- Approved events are public; pending/rejected items are visible to admins.

insert into public.events (
  id, title, description, category, city, venue_name, venue_address,
  latitude, longitude, starts_at, ends_at, image_url, registration_url,
